function bankSelect(id){return `<select id="${id}" required><option value="" disabled selected>Select your bank</option>${BANK_LIST.map(b=>`<option value="${depEsc(b)}">${depEsc(b)}</option>`).join('')}</select>`;}

/* ===== GAME PLATFORMS: the Slot Games list staff manage in Admin -> Slot Games (logo, name, link). Shows the player's own ID per platform. ===== */
let gpLoading=false;
async function loadPlatforms(){if(gpLoading)return;gpLoading=true;try{const r=await fetch('/api/slots/list',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}',cache:'no-store'});const d=await r.json();state.platforms=(d&&d.platforms)||[];state.platformsAt=Date.now();}catch(e){state.platforms=[];state.platformsAt=Date.now();}finally{gpLoading=false;if(state.page==='platforms')render();}}
function gpKey(n){return String(n||'').toLowerCase().replace(/[^a-z0-9]/g,'');}
function gpMyId(name){const k=gpKey(name);const ids=(state.game_ids||[]).filter(x=>x.game_id&&(gpKey(x.platform)===k||gpKey(x.label)===k));return ids.length?ids[0].game_id:'';}
platformsPage=()=>{const list=state.platforms;
 if(!list)return `<div class="gp-wrap"><div class="empty">Loading game platforms…</div></div>`;
 const cards=list.map(p=>{const links=(Array.isArray(p.links)&&p.links.length?p.links:(p.play_url?[{label:p.kind==='web'?'Play now':'Download',url:p.play_url}]:[])).filter(l=>l&&l.url);const mine=gpMyId(p.name);const mark=p.logo_url?`<img class="gp-logo" src="${depEsc(p.logo_url)}" alt="" loading="lazy">`:`<span class="gp-logo gp-text">${depEsc(String(p.name||'?').slice(0,1).toUpperCase())}</span>`;
  const info=`<div class="gp-info"><b>${depEsc(p.name)}</b>${mine?`<small>Your ID · <code>${depEsc(mine)}</code> <button type="button" class="gp-copy" data-copy="${depEsc(mine)}">Copy</button></small>`:`<small>${p.kind==='web'?'Play in browser':'Mobile app'}</small>`}</div>`;
  const a=l=>`<a class="gp-btn" href="${depEsc(l.url)}" target="_blank" rel="noopener">${depEsc(l.label||'Open')} ›</a>`;
  if(!links.length)return `<article class="gp-card">${mark}${info}<span class="gp-btn soon">Coming soon</span></article>`;
  if(links.length===1)return `<article class="gp-card">${mark}${info}${a(links[0])}</article>`;
  return `<article class="gp-card gp-multi">${mark}${info}<div class="gp-links">${links.map(a).join('')}</div></article>`;}).join('');
 return `<div class="gp-wrap"><p class="subtitle" style="margin:0 0 12px">Tap a link to open or download the game. Your game IDs are set by support.</p>${cards||'<div class="empty">No game platforms listed yet — ask support in Chat.</div>'}</div>`;};
function wirePlatforms(){document.querySelectorAll('.gp-copy').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(b.dataset.copy);b.textContent='Copied';setTimeout(()=>b.textContent='Copy',1500);}catch(e){toast('Copy unavailable — long-press the ID to copy it.');}});}

/* ===== LIVE CHAT: real conversation with support (same inbox staff use in Admin -> Messages). ===== */
const chatState={msgs:[],lastId:0,loaded:false,timer:null,sending:false,q:''};
function chatText(m){const b=m.is_html?String(m.body||'').replace(/<[^>]+>/g,' '):String(m.body||'');return (b+(m.image_url?' photo':'')).replace(/\s+/g,' ').trim();}
function chatMatch(m){return !chatState.q||chatText(m).toLowerCase().includes(chatState.q);}
function chatMark(escaped){const q=depEsc(chatState.q);if(!q)return escaped;const re=new RegExp(q.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'ig');return escaped.replace(re,x=>'<mark>'+x+'</mark>');}
function chatKeepNote(){const n=Number(memberData&&memberData.settings&&memberData.settings.chat_keep)||100;return 'Only the last '+n+' messages are kept';}
function chatFmt(m){const d=m.created_at?new Date(m.created_at):new Date();const t=d.toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'});const side=m.sender==='player'?'outgoing':'incoming';const body=m.is_html?String(m.body||''):chatMark(depEsc(m.body||'')).replace(/\n/g,'<br>');
 return `<div class="message-row ${side}${chatState.q?' is-result':''}" data-id="${m.id}">${side==='incoming'?'<span class="support-avatar">'+icon('chat')+'</span>':''}<div class="message-content">${side==='incoming'?'<span class="message-sender">LE888 Support</span>':''}${m.image_url?`<a class="message-image" href="${depEsc(m.image_url)}" target="_blank" rel="noopener"><img src="${depEsc(m.image_url)}" alt="" loading="lazy"></a>`:''}${body?`<div class="message-bubble">${body}</div>`:''}<time>${t}${m.pending?' · Sending…':''}</time></div></div>`;}
function chatListHtml(){if(!chatState.loaded)return '<div class="chat-date">Loading…</div>';const q=chatState.q;const list=q?chatState.msgs.filter(chatMatch):chatState.msgs;if(!list.length)return '<div class="chat-date">'+(q?'No messages match “'+depEsc(chatState.q)+'”':'Say hello — our team replies here.')+'</div>';return list.map(chatFmt).join('');}
function chatPaint(){const tl=document.querySelector('#chat-messages');if(!tl)return;tl.innerHTML=chatListHtml();tl.classList.toggle('searching',!!chatState.q);const info=document.querySelector('#chat-q-info');if(info){if(chatState.q){const n=chatState.msgs.filter(chatMatch).length;info.textContent=n?n+' of '+chatState.msgs.length+' messages match · tap one to jump to it':'Nothing found in your last '+chatState.msgs.length+' messages';info.hidden=false;}else info.hidden=true;}const clr=document.querySelector('#chat-q-clear');if(clr)clr.hidden=!chatState.q;}
function chatSetQuery(v){chatState.q=String(v||'').trim().toLowerCase();chatPaint();if(!chatState.q)chatBottom(false);}
function chatJump(id){const inp=document.querySelector('#chat-q');if(inp)inp.value='';chatState.q='';chatPaint();const row=document.querySelector('#chat-messages .message-row[data-id="'+id+'"]');if(!row)return;row.scrollIntoView({block:'center',behavior:'instant'});row.classList.add('flash');setTimeout(()=>row.classList.remove('flash'),1700);}
chat=function(){const canImg=!!(memberData.settings&&memberData.settings.images);
 return `<div class="chat-search" role="search"><svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/></svg><input id="chat-q" type="search" placeholder="Search messages" autocomplete="off" aria-label="Search messages" value="${depEsc(chatState.q)}"><button type="button" id="chat-q-clear" aria-label="Clear search" ${chatState.q?'':'hidden'}>×</button></div><div class="chat-search-info" id="chat-q-info" hidden></div><div class="chat-conversation" id="chat-scroll" tabindex="0" aria-label="Conversation history"><div class="chat-timeline${chatState.q?' searching':''}" id="chat-messages" role="log" aria-live="polite" aria-relevant="additions">${chatListHtml()}</div></div><button id="chat-new-message" class="chat-new-message" hidden>New message ↓</button><div class="chat-composer"><form id="chat-form" class="ios-message-form">${canImg?`<label class="chat-attach" for="chat-file" aria-label="Send a photo">${icon('photo')}<input id="chat-file" type="file" accept="image/*" style="display:none"></label>`:''}<textarea id="message-text" aria-label="Message" placeholder="Message…" rows="1" maxlength="1000"></textarea><button id="chat-send" type="submit" aria-label="Send message" disabled><svg class="icon" viewBox="0 0 24 24"><path d="M12 19V5m-6 6 6-6 6 6"/></svg></button></form><div class="chat-preview-note">Replies usually within a few minutes · ${chatKeepNote()}</div></div>`;};
async function chatLoad(initial){try{const d=await memberRequest('chat/list',{after_id:initial?0:chatState.lastId});const incoming=(d.messages||[]);const del=new Set(d.deleted_ids||[]);
 if(initial){chatState.msgs=incoming;}else{incoming.forEach(m=>{if(!chatState.msgs.some(x=>x.id===m.id))chatState.msgs.push(m);});}
 if(del.size)chatState.msgs=chatState.msgs.filter(m=>!del.has(m.id));chatState.msgs.forEach(m=>{if(m.id>chatState.lastId)chatState.lastId=m.id;});chatState.loaded=true;
 if(memberData){memberData.chat_unread=0;chatDot();}
 if(state.page==='chat'){const tl=document.querySelector('#chat-messages');if(tl){const area=document.querySelector('#chat-scroll');const atBottom=!area||area.scrollHeight-area.scrollTop-area.clientHeight<80;if(initial||incoming.length||del.size)chatPaint();if(chatState.q){if(incoming.length)chatPaint();}else if(atBottom||initial||incoming.length)chatBottom(!initial);}}
}catch(e){if(initial&&state.page==='chat')toast(e&&e.message?e.message:'Could not load chat.');}}
function chatStart(){chatStop();chatLoad(!chatState.loaded);chatState.timer=setInterval(()=>{if(state.page==='chat'&&!document.hidden)chatLoad(false);else chatStop();},5000);}
function chatStop(){if(chatState.timer){clearInterval(chatState.timer);chatState.timer=null;}}
async function chatSendMsg(text,imageUrl){if(chatState.q){const inp=document.querySelector('#chat-q');if(inp)inp.value='';chatSetQuery('');}const tmp={id:'tmp'+Date.now(),sender:'player',body:text,image_url:imageUrl||'',created_at:new Date().toISOString(),pending:true};chatState.msgs.push(tmp);const tl=document.querySelector('#chat-messages');if(tl){tl.insertAdjacentHTML('beforeend',chatFmt(tmp));chatBottom();}
 try{const r=await memberRequest('chat/send',{body:text,image_url:imageUrl||''});tmp.id=r.id;tmp.pending=false;if(r.id>chatState.lastId)chatState.lastId=r.id;const row=tl&&tl.querySelector('.message-row[data-id^="tmp"]');if(row)row.outerHTML=chatFmt(tmp);}
 catch(e){chatState.msgs=chatState.msgs.filter(m=>m!==tmp);const row=tl&&tl.querySelector('.message-row[data-id^="tmp"]');if(row)row.remove();toast(e&&e.message?e.message:'Message not sent. Please try again.');}}
wireChat=function(){const form=document.querySelector('#chat-form');if(!form)return;const input=document.querySelector('#message-text'),send=document.querySelector('#chat-send'),area=document.querySelector('#chat-scroll');
 function resize(){input.style.height='auto';input.style.height=Math.min(input.scrollHeight,112)+'px';send.disabled=!input.value.trim();}input.oninput=resize;input.onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();form.requestSubmit();}};
 form.onsubmit=e=>{e.preventDefault();const text=input.value.trim();if(!text||chatState.sending)return;input.value='';resize();chatSendMsg(text,'');input.focus();};
 const file=document.querySelector('#chat-file');const sendPhoto=async f=>{if(!f||!/^image\//.test(f.type))return;toast('Sending photo…');try{const blob=await depShrink(f);const r=await fetch('/api/member/chat/upload',{method:'POST',headers:{'Content-Type':blob.type},body:blob,cache:'no-store'});const j=await r.json().catch(()=>({}));if(!r.ok||!j.ok)throw new Error(j.error||'Photo upload failed.');await chatSendMsg('',j.url);}catch(err){toast(err&&err.message?err.message:'Photo not sent.');}};if(memberData.settings&&memberData.settings.images)input.addEventListener('paste',e=>{const it=[...((e.clipboardData&&e.clipboardData.items)||[])].find(x=>x.type&&x.type.indexOf('image/')===0);if(it){e.preventDefault();sendPhoto(it.getAsFile());}});if(file)file.onchange=async()=>{const f=file.files&&file.files[0];if(!f)return;file.value='';toast('Sending photo…');try{const blob=await depShrink(f);const r=await fetch('/api/member/chat/upload',{method:'POST',headers:{'Content-Type':blob.type},body:blob,cache:'no-store'});const j=await r.json().catch(()=>({}));if(!r.ok||!j.ok)throw new Error(j.error||'Photo upload failed.');await chatSendMsg('',j.url);}catch(err){toast(err&&err.message?err.message:'Photo not sent.');}};
 const qi=document.querySelector('#chat-q'),qc=document.querySelector('#chat-q-clear'),tlEl=document.querySelector('#chat-messages');let qt=null;if(qi){qi.oninput=()=>{clearTimeout(qt);qt=setTimeout(()=>chatSetQuery(qi.value),120);};qi.onkeydown=e=>{if(e.key==='Escape'){qi.value='';chatSetQuery('');qi.blur();}};}
 if(qc)qc.onclick=()=>{if(qi)qi.value='';chatSetQuery('');};if(tlEl)tlEl.onclick=e=>{if(!chatState.q||e.target.closest('a'))return;const row=e.target.closest('.message-row.is-result');if(row)chatJump(row.dataset.id);};if(chatState.q)chatPaint();
 const nm=document.querySelector('#chat-new-message');if(nm)nm.onclick=()=>chatBottom();if(area)area.onscroll=()=>{if(area.scrollHeight-area.scrollTop-area.clientHeight<35&&nm)nm.hidden=true;};resize();requestAnimationFrame(()=>chatBottom(false));chatStart();};
function chatDot(){const n=Number(memberData&&memberData.chat_unread)||0;document.querySelectorAll('.chat-dot').forEach(d=>{d.style.display=n>0?'':'none';});const nb=document.querySelector('#os-notifications i');if(nb){nb.textContent=String(n);nb.style.display=n>0?'':'none';}}

/* ===== REWARDS: daily check-in, VIP weekly bonus, promotions — all from Admin. ===== */
let rwLoading=false;
async function loadRewards(){if(rwLoading)return;rwLoading=true;try{const [prof,vip,promos]=await Promise.all([memberRequest('profile',{}).catch(()=>null),memberRequest('vip',{}).catch(()=>null),memberRequest('promos',{}).catch(()=>null)]);state.rw={checkin:prof&&prof.checkin,tasks:(prof&&prof.tasks)||[],vip:vip,promos:(promos&&promos.promos)||[],bonus:(promos&&promos.deposit_bonus&&promos.deposit_bonus.tiers)||[]};state.rwAt=Date.now();if(prof&&prof.player&&typeof prof.player.points==='number'){memberData.member.points=prof.player.points;}}catch(e){state.rw=state.rw||{};}finally{rwLoading=false;if(['rewards','missions','deposit-bonus','promotions'].includes(state.page))render();}}
function rwNeed(){if(!state.rw||Date.now()-(state.rwAt||0)>20000)loadRewards();}
function rewardsPage(){const r=state.rw;if(!r)return '<div class="empty">Loading rewards…</div>';const c=r.checkin,v=r.vip;
 const days=(c&&c.rewards)||[1,2,3,4,5,8,10];const cur=c?c.current_day:1;
 const checkin=`<div class="reward-card rw-card"><h2>DAILY CHECK-IN</h2><p>${c?('Streak: '+c.standing_streak+' day'+(c.standing_streak===1?'':'s')+(c.min_deposit>0?' · deposit SGD '+c.min_deposit+' today to check in':'')):'7-day streak rewards'}</p><div class="days days7">${days.map((pts,i)=>`<div class="day ${c&&c.checked_in_today&&i+1===cur?'done':''} ${c&&!c.checked_in_today&&i+1===cur?'today':''} ${i+1<cur?'past':''}"><small>DAY ${i+1}</small><b>+${pts}</b></div>`).join('')}</div>${c?(c.checked_in_today?'<button class="primary-btn" disabled>Checked in today ✓</button>':(c.can_check_in?`<button class="primary-btn" id="rw-checkin">Check in · +${c.current_points} PTS</button>`:`<button class="primary-btn" disabled>Deposit SGD ${c.min_deposit} today to check in</button>`)):''}</div>`;
 const weekly=v?`<div class="panel rw-row"><div>${vipBadge((vipList()[v.rank_idx]||vipList()[0]),v.rank_idx<0)}</div><div class="rw-copy"><b>VIP Weekly Bonus</b><small>${v.rank_idx>=0?(v.rank_name+' · +'+v.weekly_points+' PTS every week'):'Reach a VIP rank to unlock'}</small></div>${v.rank_idx>=0?(v.weekly_claimed?'<span class="dep-chip approved">CLAIMED</span>':'<button class="gp-btn" id="rw-weekly">Claim</button>'):'<button class="gp-btn ghost" data-go="vip">Ranks</button>'}</div>`:'';
 const promos=(r.promos||[]).map(p=>{const gated=p.access==='gated';const avail=gated?p.available_unlocks>0:(p.limit_type==='day'?p.claimed_today<Math.max(1,p.limit_count||1):p.claimed_total<Math.max(1,p.limit_count||1));const reward=p.reward_type==='credits'?('SGD '+(Number(p.points)/100).toFixed(2)+' credit'):('+'+p.points+' PTS');
  return `<div class="panel rw-promo">${p.image_url?`<img src="${depEsc(p.image_url)}" alt="">`:''}<div class="rw-promo-body"><b>${depEsc(p.title)}</b>${p.tnc?`<small>${depEsc(p.tnc)}</small>`:''}<div class="rw-promo-foot"><span class="pill">${reward}</span>${avail?`<button class="gp-btn" data-promo="${p.id}">Claim</button>`:`<span class="dep-chip ${gated?'pending':'approved'}">${gated?'LOCKED':(p.limit_type==='day'?'CLAIMED TODAY':'CLAIMED')}</span>`}</div></div></div>`;}).join('');
 return `<div class="rw-wrap">${Number(memberReward())>0?`<button type="button" class="rw-claim-card panel" data-go="wallet">${icon('gift')}<span><small>REWARD CREDITS WON</small><b>SGD ${memberReward()}</b><em>Tap to submit to your free-credit game account</em></span><i>›</i></button>`:''}${checkin}${weekly}<h3 class="dep-h" style="margin-top:16px">Promotions</h3>${promos||'<div class="empty">No promotions right now — check back soon.</div>'}${menuList([['gift','Deposit Bonus','deposit-bonus'],['calendar','Missions','missions']])}</div>`;}
function missionsPage(){const r=state.rw;if(!r)return '<div class="empty">Loading missions…</div>';const t=r.tasks||[];const on=!!(memberData.settings&&memberData.settings.tasks_enabled);
 if(!on||!t.length)return `<div class="form-panel panel"><h2>Missions</h2><p class="subtitle" style="margin-top:12px">No missions right now — new ones appear here when available.</p></div>`;
 return `<div class="rw-wrap">${t.map(x=>`<div class="mission panel">${icon('calendar')}<div class="mission-copy"><p>${depEsc(x.title)}</p>${x.description?`<small>${depEsc(x.description)}</small>`:''}${x.url?`<a class="text-link" href="${depEsc(x.url)}" target="_blank" rel="noopener">Open ›</a>`:''}</div>${x.completed?'<span class="dep-chip approved">DONE</span>':`<button class="gp-btn" data-task="${x.id}">+${x.points} PTS</button>`}</div>`).join('')}</div>`;}
function depositBonusPage(){const r=state.rw;if(!r)return '<div class="empty">Loading…</div>';const tiers=r.bonus||[];const per={today:'today',week:'this week',month:'this month',lifetime:'in total'};
 const cards=tiers.map(t=>{const pct=Math.max(0,Math.min(100,Math.round((t.period_total/Math.max(1,t.min_deposit))*100)));const reward=t.reward_type==='credits'?('SGD '+(Number(t.amount)/100).toFixed(2)+' credit'):('+'+t.amount+' PTS');
  return `<div class="panel rw-promo">${t.image_url?`<img src="${depEsc(t.image_url)}" alt="">`:''}<div class="rw-promo-body"><b>${depEsc(t.title||('Deposit SGD '+t.min_deposit))}</b><small>Deposit SGD ${Number(t.min_deposit).toLocaleString('en-US')} ${per[t.period]||''} · you: SGD ${Number(t.period_total).toLocaleString('en-US')}</small><div class="progress"><i style="width:${pct}%"></i></div><div class="rw-promo-foot"><span class="pill">${reward}</span>${t.claimed?'<span class="dep-chip approved">CLAIMED</span>':(t.reached?`<button class="gp-btn" data-bonus="${t.id}">Claim</button>`:`<span class="dep-chip pending">${pct}%</span>`)}</div></div></div>`;}).join('');
 return `<div class="rank-card panel">${icon('gift')}<h2>DEPOSIT BONUS</h2><p>Deposit, hit the target, claim the bonus.</p></div><div class="rw-wrap" style="margin-top:12px">${cards||'<div class="empty">No deposit bonus running right now.</div>'}</div>${button('Deposit now','deposit','primary-btn')}`;}
function wireRewards(){const ci=document.querySelector('#rw-checkin');if(ci)ci.onclick=async()=>{ci.disabled=true;try{const r=await memberRequest('checkin',{});memberData.member.points=r.points;toast('Checked in! +'+r.points_added+' PTS (day '+r.day+')');state.rwAt=0;await loadRewards();}catch(e){ci.disabled=false;toast(e&&e.message?e.message:'Could not check in.');}};
 const wk=document.querySelector('#rw-weekly');if(wk)wk.onclick=async()=>{wk.disabled=true;try{const r=await memberRequest('vip/claim-weekly',{});if(typeof r.points==='number')memberData.member.points=r.points;toast('Weekly bonus claimed! +'+(r.points_added||'')+' PTS');state.rwAt=0;await loadRewards();}catch(e){wk.disabled=false;toast(e&&e.message?e.message:'Could not claim.');}};
 document.querySelectorAll('[data-promo]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const r=await memberRequest('promos/claim',{promo_id:Number(b.dataset.promo)});if(r.reward_type==='credits'){memberData.member.reward=r.reward;toast('Claimed! SGD '+(Number(r.amount)/100).toFixed(2)+' reward credit added.');}else{memberData.member.points=r.points;toast('Claimed! +'+r.points_added+' PTS');}state.rwAt=0;await loadRewards();}catch(e){b.disabled=false;toast(e&&e.message?e.message:'Could not claim.');}});
 document.querySelectorAll('[data-task]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const r=await memberRequest('task/complete',{task_id:Number(b.dataset.task)});memberData.member.points=r.points;toast('Mission done! +'+r.points_added+' PTS');state.rwAt=0;await loadRewards();}catch(e){b.disabled=false;toast(e&&e.message?e.message:'Could not complete.');}});
 document.querySelectorAll('[data-bonus]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const r=await memberRequest('deposit-bonus/claim',{tier_id:Number(b.dataset.bonus)});if(r.reward_type==='credits'){memberData.member.reward=r.reward;toast('Bonus claimed! SGD '+(Number(r.amount)/100).toFixed(2)+' credit added.');}else{if(typeof r.points==='number')memberData.member.points=r.points;toast('Bonus claimed! +'+(r.points_added||r.amount)+' PTS');}state.rwAt=0;await loadRewards();}catch(e){b.disabled=false;toast(e&&e.message?e.message:'Could not claim.');}});}

/* ===== WALLET: reward credits -> send to Free Credit account (staff approve), with history. ===== */
let wlLoading=false;
async function loadWallet(){if(wlLoading)return;wlLoading=true;try{const [h,prof]=await Promise.all([memberRequest('history',{}).catch(()=>null),memberRequest('profile',{}).catch(()=>null)]);state.wallet={payouts:(h&&h.payouts)||[],cooldown:prof?Number(prof.submit_cooldown)||0:0,lock:!!(prof&&prof.credit_lock)};state.walletAt=Date.now();if(prof&&prof.player){if(typeof prof.player.points==='number')memberData.member.points=prof.player.points;if(prof.player.reward!==undefined)memberData.member.reward=prof.player.reward;}}catch(e){state.wallet=state.wallet||{payouts:[]};}finally{wlLoading=false;if(state.page==='wallet')render();}}
function walletPage(){const w=state.wallet;const free=(state.free_ids||[]).filter(x=>x.game_id);const cents=Math.round(Number(memberReward())*100);const pend=w&&(w.payouts||[]).find(p=>p.status==='pending');
 const action=!w?'<div class="empty">Loading…</div>':pend?`<div class="notice">Your submission of SGD ${depEsc(pend.amount)} is being processed by our team.</div>`:(cents<=0?'<p class="subtitle">Play the mini games to earn reward credits, then send them to your free-credit game account here.</p>':(!free.length?`<div class="form-panel panel" style="margin-top:12px"><h3 class="dep-h">Send SGD ${memberReward()} to</h3><p class="subtitle" style="margin:0 0 10px">Choose the game for your free credit. Our team creates your account and sends the login in Chat.</p><div class="wd-srcs">${[['pussy888','Pussy888'],['mega888','Mega888']].map((g,i)=>`<label class="wd-src${i===0?' on':''}"><input type="radio" name="wl-plat" value="${g[0]}" ${i===0?'checked':''}><span class="wd-src-body"><b>${g[1]}</b><small>New free-credit account</small></span></label>`).join('')}</div>${w.cooldown>0?`<button class="primary-btn" disabled>Wait ${Math.ceil(w.cooldown/60)} min</button>`:`<button class="primary-btn" id="wl-submit">Submit SGD ${memberReward()}</button>`}</div>`:`<div class="form-panel panel" style="margin-top:12px"><h3 class="dep-h">Send SGD ${memberReward()} to</h3><label for="wl-id">Free credit account</label><select id="wl-id">${free.map(x=>`<option value="${depEsc(x.platform)}|${depEsc(x.game_id)}">${depEsc(x.label)} · ${depEsc(x.game_id)}</option>`).join('')}</select>${w.cooldown>0?`<button class="primary-btn" disabled>Wait ${Math.ceil(w.cooldown/60)} min</button>`:`<button class="primary-btn" id="wl-submit">Submit SGD ${memberReward()}</button>`}<p class="subtitle" style="margin-top:10px">Our team loads the credit into that game account and messages you with the withdrawal rule.</p></div>`));
 const hist=w?(w.payouts||[]).map(p=>`<div class="dep-item"><span class="dep-noimg">${icon('gift')}</span><div class="dep-meta"><b>SGD ${depEsc(p.amount)}</b><small>${p.fc_custom?'VIP free credit':'Reward submitted'} · ${depWhen(p.created_at)}${p.status==='approved'&&p.game_id?' · '+depEsc(p.game||'')+' '+depEsc(p.game_id):''}${p.status==='approved'&&p.winover!=null?' · winover ×'+depEsc(p.winover)+(p.withdraw?' · withdraw SGD '+depEsc(p.withdraw):''):''}</small></div><span class="dep-chip ${p.status==='approved'?'approved':p.status==='rejected'?'rejected':'pending'}">${p.status==='approved'?'CREDITED':p.status==='rejected'?'REJECTED':'PENDING'}</span></div>`).join(''):'';
 return balance()+`<div class="balance panel">${icon('gift')}<div><small>Reward Credits</small><strong>SGD ${memberReward()}</strong></div></div>${action}<section class="dep-history"><h3 class="dep-h">Reward credit history</h3>${hist||'<div class="empty">Nothing yet.</div>'}</section>`+menuList([['history','PTS History','history']]);}
function wireWallet(){document.querySelectorAll('input[name="wl-plat"]').forEach(r=>r.onchange=()=>document.querySelectorAll('input[name="wl-plat"]').forEach(x=>x.closest('.wd-src').classList.toggle('on',x.checked)));const b=document.querySelector('#wl-submit');if(!b)return;b.onclick=async()=>{const sel=document.querySelector('#wl-id');const pr=document.querySelector('input[name="wl-plat"]:checked');let [platform,gid]=(sel&&sel.value||'|').split('|');if(!sel&&pr){platform=pr.value;gid='';}const where=gid||(platform==='mega888'?'a new Mega888 account':'a new Pussy888 account');if(!confirm('Send SGD '+memberReward()+' reward credit to '+where+'? Your reward balance becomes 0 while our team processes it.'))return;b.disabled=true;try{const r=await memberRequest('reward/submit',{platform,game_id:gid});if(r.reward!==undefined)memberData.member.reward=r.reward;toast('Submitted! Our team will credit your game account.');state.walletAt=0;await loadWallet();}catch(e){b.disabled=false;toast(e&&e.message?e.message:'Could not submit.');}};}


/* ===== TERMS (Admin -> Settings), SUPPORT ===== */
const TERMS_DEFAULT=`1. LE888 is a rewards app for our community members. Points (PTS) and reward credits have no cash value and cannot be exchanged for cash inside the app.\n\n2. PTS are awarded by our team (deposits, check-ins, promotions, missions) and are spent on mini games. Game outcomes are decided by our server; odds are shown per game.\n\n3. Reward credits won in mini games are sent to your free-credit game account on request and are subject to the winover rule shown on approval.\n\n4. Deposits are made outside the app directly to the account shown on the Deposit page. Submit your receipt in the app; PTS are credited after our team verifies the transfer.\n\n5. Withdrawals are paid to the bank account saved in your profile. Bank details can be set once by you and changed only by our team.\n\n6. One account per person. Accounts found abusing promotions may have rewards voided.\n\n7. We may update these terms at any time; the latest version is always shown here.`;
function termsPage(){const t=(memberData.settings&&memberData.settings.terms_text)||TERMS_DEFAULT;const paras=String(t).split(/\n\s*\n/).map(p=>'<p>'+depEsc(p).replace(/\n/g,'<br>')+'</p>').join('');return `<div class="form-panel panel terms"><h2>Terms &amp; Conditions</h2>${paras}</div>`;}
support=()=>{const cu=memberData.settings&&memberData.settings.contact_url;return `<p class="subtitle">We're here to help with your account, rewards and games.</p>`+menuList([['chat','Live Chat','chat'],['deposit','Deposit & Withdrawal Help','payment-help'],['gift','Reward Help','reward-help']])+(cu?`<a class="primary-btn support-contact" href="${depEsc(cu)}" target="_blank" rel="noopener">Contact us ›</a>`:'')+`<p class="play-note">Our team usually replies in Live Chat within a few minutes.</p>`;};
/* ===== Bank details: saved once by the player (Account Details or Withdraw page); afterwards only staff can change them in Admin. ===== */
function memberBankSaved(){const b=memberData&&memberData.bank;return !!(b&&b.bank_name&&b.bank_account&&b.bank_holder);}
function bankGate(){/* No forced gate: players add bank details once from Account Details or Withdraw. Kept as a no-op so the call sites stay valid. */const has=document.querySelector('#bank-gate');if(has)has.remove();document.body.classList.remove('gate-open');}
const memberOriginalRender=render;render=function(){if(state.page!=='chat')chatStop();memberOriginalRender();chatDot();if(state.page==='game'&&typeof scheduleFit==='function')setTimeout(scheduleFit,0);
 if(state.page==='terms')screen.innerHTML=termsPage();

 if(state.page==='deposit-bonus'){rwNeed();screen.innerHTML=depositBonusPage();bind();wireRewards();}
 if(state.page==='rewards'||state.page==='missions'){rwNeed();wireRewards();}
 if(state.page==='wallet'){if(!state.wallet||Date.now()-(state.walletAt||0)>20000)loadWallet();wireWallet();}
 if(state.page==='invite'){const sh=document.querySelector('#invite-share');if(sh)sh.onclick=async()=>{const url=location.origin+'/install';try{if(navigator.share){await navigator.share({title:'LE888',text:'Join me on LE888',url});}else{await navigator.clipboard.writeText(url);toast('Link copied — send it to your friend.');}}catch(e){}};document.querySelectorAll('.dep-copy').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(b.dataset.copy);b.textContent='Copied';setTimeout(()=>b.textContent='Copy',1500);}catch(e){toast('Copy unavailable — long-press the link.');}});}
 if(state.page==='settings'){document.querySelectorAll('.settings-row').forEach(r=>{const t=(r.querySelector('span')||{}).textContent||'';if(/Language|Dark Mode/.test(t))r.remove();});const v=document.querySelector('[data-toggle="vibration"]');if(v){v.classList.toggle('on',state.vibration!==false);v.onclick=()=>{state.vibration=state.vibration===false;try{localStorage.setItem('le888-vib',state.vibration?'1':'0');}catch(e){}v.classList.toggle('on',state.vibration);if(state.vibration&&navigator.vibrate)navigator.vibrate(30);};}const sd=document.querySelector('[data-toggle="sound"]');if(sd)sd.closest('.settings-row').remove();const nt=document.querySelector('[data-toggle="notifications"]');if(nt)nt.closest('.settings-row').remove();}if(state.page==='deposit'){if(!state.deposit||Date.now()-(state.depositAt||0)>20000)loadDeposit();wireDeposit();}if(state.page==='withdraw'){if(!state.withdraw||Date.now()-(state.withdrawAt||0)>20000)loadWithdraw();wireWithdraw();}if(state.page==='account')wireWithdraw();if(state.page==='platforms'){if(!state.platforms||Date.now()-(state.platformsAt||0)>60000)loadPlatforms();wirePlatforms();}const signout=document.querySelector('#signout');if(signout)signout.onclick=memberLogout;
 const label=document.querySelector('.preview-label');if(label)label.textContent='MEMBER ACCOUNT · GAMES IN PREVIEW';
 document.querySelector('.os-live-missions')?.remove();
 if(state.page==='game'&&!games[state.game].soon){const lg=games[state.game],lc=(lg&&typeof gameConf==='function')?gameConf(lg.id):null;const lv={plinko:'drop',scratch:'flip',cross:'game',crown:'game',wheel:'spin',egg:'vault'}[lg&&lg.id]||'play';screen.insertAdjacentHTML('afterbegin',lc?('<div class="notice">'+(lc.enabled?('Each '+lv+' costs '+lc.cost+' PTS · prizes are reward credits (SGD).'):(lg.name+' is currently switched off.'))+'</div>'):'<div class="notice">Game preview only · No PTS are spent or awarded.</div>');}
 if(state.page==='submit'){setTimeout(()=>go('wallet'),0);}
 if(state.page==='profile'){const b=document.querySelector('.member .vip-badge');if(b)b.innerHTML=icon('crown')+' '+((memberData.vip&&memberData.vip.rank_name)?String(memberData.vip.rank_name).toUpperCase():'NO RANK');}
 const pw=document.querySelector('#password-form');if(pw){const next=pw.querySelector('#new-pass');next.minLength=10;next.maxLength=128;pw.insertAdjacentHTML('beforeend','<p class="subtitle">Use at least 10 characters. Updating your password signs out all your sessions.</p>');pw.onsubmit=async e=>{e.preventDefault();const button=pw.querySelector('button');button.disabled=true;try{await memberRequest('password',{currentPassword:pw.querySelector('#old-pass').value,newPassword:next.value});location.replace('/login?password=changed');}catch(err){toast(err.message);button.disabled=false;}};}
};
let updatingMember=false;
async function syncMember(){if(updatingMember||document.hidden)return;updatingMember=true;try{const fresh=await memberRequest('me'),changed=fresh.member.points!==memberData.member.points||fresh.member.reward!==memberData.member.reward||fresh.ledger.length!==memberData.ledger.length;const accChanged=JSON.stringify([fresh.game_ids,fresh.free_ids])!==JSON.stringify([memberData.game_ids,memberData.free_ids]);window.memberData=fresh;memberAccounts();bankGate();chatDot();if((changed||accChanged)&&!state.busy&&state.page!=='game'&&!document.querySelector('dialog[open]'))render();/* never rebuild a game board mid-session: traffic/cards would vanish */}catch(e){/* Login redirect is handled centrally; transient failures leave existing data visible. */}finally{updatingMember=false;}}
document.addEventListener('visibilitychange',syncMember);window.addEventListener('focus',syncMember);window.addEventListener('pageshow',e=>{if(e.persisted){document.body.classList.add('member-loading');location.reload();}});setInterval(syncMember,30000);
render();bankGate();

/* ===== PROFILE AVATAR: 9 characters, saved to the player's account ===== */
const AVATARS=['Lion','Chick','Bunny','Fox','Tiger','Panda','Bear','Dragon','Lucky Cat'];
function avatarNum(){const n=Number(memberData&&memberData.member&&memberData.member.avatar)||0;return n>=1&&n<=9?n:0;}
function avatarSrc(n){return '/assets/avatar/avatar-'+n+'.webp';}
/* Home welcome strip: rank shown as its medal instead of words. */
function rankMedal(){const v=memberData&&memberData.vip;const keys=['member','silver','gold','platinum','diamond','royal','legend'];let i=v?Number(v.rank_idx):-1;if(!(i>=0))i=-1;
 if(i<0)return {key:'none',name:'No Rank'};const r=v&&Array.isArray(v.ranks)?v.ranks[i]:null;const key=(r&&r.key)||keys[i]||'member';const name=(v&&v.rank_name)||(r&&r.name)||'Member';return {key,name};}
function paintRankMedal(){const el=document.querySelector('.os-vip');if(!el)return;const m=rankMedal();if(el.dataset.rk===m.key)return;el.dataset.rk=m.key;el.classList.add('os-vip-medal');el.title=m.key==='none'?'No Rank':m.name+' VIP';el.setAttribute('aria-label',m.key==='none'?'No VIP rank yet':m.name+' VIP rank');el.innerHTML=`<img src="/assets/vip-${m.key}.webp" alt="${depEsc(m.name)}">`;}
function paintAvatars(){paintRankMedal();paintBell();const n=avatarNum();
 document.querySelectorAll('.avatar,.os-avatar').forEach(el=>{
  const editable=!!el.closest('#modal .member,#screen .member');
  if(el.dataset.av!==String(n)){el.dataset.av=String(n);el.innerHTML=n?`<img class="av-img" src="${avatarSrc(n)}" alt="${AVATARS[n-1]}">`:icon('user');el.classList.toggle('has-av',!!n);}
  if(editable&&!el.dataset.avWired){el.dataset.avWired='1';el.classList.add('av-edit');el.setAttribute('role','button');el.setAttribute('tabindex','0');el.setAttribute('aria-label','Change avatar');
   el.insertAdjacentHTML('beforeend','<i class="av-pen" aria-hidden="true">✎</i>');
   const open=e=>{e.preventDefault();e.stopPropagation();openAvatarPicker();};el.addEventListener('click',open);el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' ')open(e);});}
  else if(editable&&!el.querySelector('.av-pen'))el.insertAdjacentHTML('beforeend','<i class="av-pen" aria-hidden="true">✎</i>');});}
function openAvatarPicker(){const cur=avatarNum();
 showModal('Choose your avatar',`<div class="av-grid">${AVATARS.map((name,i)=>`<button type="button" class="av-pick${cur===i+1?' on':''}" data-av-pick="${i+1}" aria-label="${name}"><img src="${avatarSrc(i+1)}" alt=""><span>${name}</span></button>`).join('')}</div>`);
 modal.classList.add('av-modal');
 modal.querySelectorAll('[data-av-pick]').forEach(b=>b.onclick=async()=>{const n=Number(b.dataset.avPick);if(n===avatarNum()){modal.close();return;}
  modal.querySelectorAll('[data-av-pick]').forEach(x=>x.disabled=true);b.classList.add('saving');
  try{await memberRequest('avatar',{avatar:n});memberData.member.avatar=n;modal.close();paintAvatars();toast('Avatar updated!');}
  catch(e){modal.querySelectorAll('[data-av-pick]').forEach(x=>x.disabled=false);b.classList.remove('saving');let m=modal.querySelector('.av-err');if(!m){m=document.createElement('p');m.className='av-err';modal.querySelector('.av-grid').after(m);}m.textContent=(e&&e.message&&!/not found/i.test(e.message))?e.message:'Could not save your avatar right now. Please try again later.';}});}
/* Repaint whenever the page, menu or a pop-up changes. */
(function(){let q=false;const run=()=>{q=false;try{paintAvatars();}catch(e){}};new MutationObserver(()=>{if(!q){q=true;requestAnimationFrame(run);}}).observe(document.body,{childList:true,subtree:true});run();
 [0,1,2,3,4,5,6,7,8].forEach(i=>{const im=new Image();im.src=avatarSrc(i+1);});})();


/* ===== TRANSACTION HISTORY: Points · Rewards · Deposits · Withdrawals ===== */
const HIST_TABS=[['points','Points'],['rewards','Rewards'],['deposits','Deposits'],['withdrawals','Withdrawals']];
const PT_TYPE={checkin:'Daily check-in',task_complete:'Mission reward',arcade_daily:'Daily game bonus',arcade_play:'Played a mini game',reward_submit:'Reward submitted',deposit_bonus:'Deposit bonus',promo:'Promotion',vip_weekly:'VIP weekly bonus',vip_upgrade:'VIP rank-up bonus',admin_correction:'Adjusted by support',system_adjustment:'Adjustment',deposit:'Deposit points',deposit_points:'Deposit points'};
const histState={data:{},at:{},loading:{}};
async function histLoad(tab,force){if(histState.loading[tab])return;if(!force&&histState.data[tab]&&Date.now()-(histState.at[tab]||0)<20000)return;histState.loading[tab]=true;
 try{let d;
  if(tab==='points'||tab==='rewards'){const h=await memberRequest('history',{});histState.data.points=h.reward||[];histState.data.rewards={activity:h.activity||[],payouts:h.payouts||[]};histState.at.points=histState.at.rewards=Date.now();}
  else if(tab==='deposits'){d=await memberRequest('deposits');histState.data.deposits=d;histState.at.deposits=Date.now();}
  else{d=await memberRequest('withdraw');histState.data.withdrawals=d.withdrawals||[];histState.at.withdrawals=Date.now();}
 }catch(e){histState.data[tab]=histState.data[tab]||{error:(e&&e.message)||'Could not load.'};}
 finally{histState.loading[tab]=false;if(state.page==='history'&&(state.histTab||'points')===tab)render();}}
function histRow(ic,title,sub,amt,cls,chip){return `<div class="dep-item"><span class="dep-noimg">${icon(ic)}</span><div class="dep-meta"><b>${title}</b><small>${sub}</small></div>${chip?`<span class="dep-chip ${chip[1]}">${chip[0]}</span>`:''}${amt!==''?`<span class="hist-amt ${cls}">${amt}</span>`:''}</div>`;}
function histChip(st){return st==='approved'||st==='paid'||st==='credited'?['DONE','approved']:st==='rejected'?['REJECTED','rejected']:['PENDING','pending'];}
function histBody(tab){const d=histState.data[tab];if(!d)return '<div class="empty">Loading…</div>';if(d.error)return `<div class="empty">${depEsc(d.error)}</div>`;
 if(tab==='points'){const rows=d.length?d:(memberData.ledger||[]).map(l=>({type:l.type,amount:l.delta,note:l.note,created_at:l.created_at}));
  return rows.length?rows.map(r=>{const a=Number(r.amount)||0;return histRow(a>=0?'gift':'games',depEsc(PT_TYPE[r.type]||(a>=0?'PTS added':'PTS used')),depWhen(r.created_at)+(r.note&&r.type==='admin_correction'?' · '+depEsc(r.note):'')+(r.points_after!=null?' · balance '+Number(r.points_after).toLocaleString('en-SG'):''),(a>0?'+':'')+a.toLocaleString('en-SG')+' PTS',a>=0?'h-in':'h-out');}).join(''):'<div class="empty">No points activity yet.</div>';}
 if(tab==='rewards'){const items=[];(d.activity||[]).filter(x=>x.kind==='game'&&x.win).forEach(x=>items.push({t:x.created_at,h:histRow('gift',depEsc(String(x.label||'').replace(/^Played /,'Won on ')),depWhen(x.created_at),'+SGD '+depEsc(x.win),'h-in')}));
  (d.payouts||[]).forEach(p=>items.push({t:p.created_at,h:histRow('withdraw',p.fc_custom?'VIP free credit':'Submitted to game account',depWhen(p.created_at)+(p.status==='approved'&&p.game_id?' · '+depEsc(p.game||'')+' '+depEsc(p.game_id):'')+(p.status==='rejected'?' · returned to your balance':''),'SGD '+depEsc(p.amount),'',histChip(p.status))}));
  items.sort((a,b)=>String(b.t).localeCompare(String(a.t)));return `<div class="hist-sum"><span>Reward credits now</span><b>SGD ${memberReward()}</b>${Number(memberReward())>0?`<button type="button" class="hist-go" data-go="wallet">Submit ›</button>`:''}</div>`+(items.length?items.map(x=>x.h).join(''):'<div class="empty">No reward activity yet. Win credits in the mini games!</div>');}
 if(tab==='deposits'){const all=(d.requests||[]).slice(0,50).map(x=>histRow('deposit','Deposit'+(x.game_id?' · '+depEsc(x.game||'')+' '+depEsc(x.game_id):''),depWhen(x.created_at)+(x.method?' · '+(x.method==='bank'?'Bank transfer':'PayNow'):'')+(x.status==='rejected'&&x.note?' · '+depEsc(x.note):''),'SGD '+Number(x.amount).toFixed(2),'',x.status==='approved'?['APPROVED','approved']:histChip(x.status)));return all.length?all.join(''):'<div class="empty">No deposits yet.</div>';}
 const w=d;return w.length?w.map(x=>histRow('withdraw',x.source_type==='free_credit'?'Free Credit ID withdrawal':'Deposit ID withdrawal',depWhen(x.created_at)+(x.source_game_id?' · '+depEsc(x.source_game||'')+' '+depEsc(x.source_game_id):'')+(x.status==='rejected'&&x.note?' · '+depEsc(x.note):''),'SGD '+depEsc(x.amount),'',histChip(x.status))).join(''):'<div class="empty">No withdrawals yet.</div>';}
transactions=()=>{const tab=state.histTab||'points';return `<div class="hist-tabs" role="tablist">${HIST_TABS.map(([k,l])=>`<button type="button" role="tab" class="hist-tab${k===tab?' on':''}" aria-selected="${k===tab}" data-hist="${k}">${l}</button>`).join('')}</div><section class="dep-history hist-list">${histBody(tab)}</section>`;};
(function(){const prev=render;render=function(){prev();if(state.page!=='history')return;const tab=state.histTab||'points';histLoad(tab);
 document.querySelectorAll('[data-hist]').forEach(b=>b.onclick=()=>{state.histTab=b.dataset.hist;render();});
 document.querySelectorAll('#screen [data-go]').forEach(b=>{if(!b.onclick)b.onclick=()=>go(b.dataset.go);});};})();


/* ===== NOTIFICATIONS (bell): only staff broadcasts. Deposits, withdrawals,
   free credit etc. are announced in Live Chat. ===== */
function noticeSeen(){try{return Number(localStorage.getItem('le888-notice-seen'))||0;}catch(e){return 0;}}
function noticeUnread(){return (Number(memberData&&memberData.notice_latest)||0)>noticeSeen();}
function paintBell(){if(state.page!=='home')return;const b=document.querySelector('#os-chat')||document.querySelector('#ios-header-action');if(!b)return;
 if(b.dataset.bell!=='1'){b.dataset.bell='1';b.setAttribute('aria-label','Notifications');b.innerHTML=icon('bell')+'<span class="notice-dot"></span>';b.onclick=e=>{e.preventDefault();openNotices();};}
 const d=b.querySelector('.notice-dot');if(d)d.style.display=noticeUnread()?'':'none';
 const st=document.querySelector('#os-notifications');if(st&&st.dataset.chat!=='1'){st.dataset.chat='1';st.setAttribute('aria-label','Live chat');st.onclick=e=>{e.preventDefault();go('chat');};}}
async function openNotices(){showModal('Notifications','<div class="nt-list"><div class="empty">Loading…</div></div>');modal.classList.add('nt-modal');
 try{const d=await memberRequest('notifications');const list=d.notifications||[];const box=modal.querySelector('.nt-list');if(!box)return;
  const seen=noticeSeen();box.innerHTML=list.length?list.map(n=>`<article class="nt-item${n.id>seen?' new':''}"><span class="nt-ic">${icon('bell')}</span><div><p>${depEsc(n.message).replace(/\n/g,'<br>')}</p><small>${depWhen(n.created_at)}</small></div></article>`).join(''):'<div class="empty">No announcements yet.<br><small>Updates about your deposits, withdrawals and free credit are sent to you in Live Chat.</small></div>';
  const top=list.length?Number(list[0].id)||0:0;const latest=Math.max(top,Number(memberData&&memberData.notice_latest)||0);try{localStorage.setItem('le888-notice-seen',String(latest));}catch(e){}if(memberData)memberData.notice_latest=latest;paintBell();}
 catch(e){const box=modal.querySelector('.nt-list');if(box)box.innerHTML='<div class="empty">Could not load notifications.</div>';}}

/* ===== INVITE FRIENDS: referral code + progress. Staff link friends; PTS arrive when the friend's deposit is keyed in. ===== */
const refState={data:null,loading:false,at:0};
async function refLoad(force){if(refState.loading)return;if(!force&&refState.data&&Date.now()-refState.at<20000)return;refState.loading=true;
 try{refState.data=await memberRequest('referrals');refState.at=Date.now();}catch(e){refState.data=refState.data||{error:(e&&e.message)||'Could not load.'};}
 finally{refState.loading=false;if(state.page==='invite')render();}}
invite=()=>{const d=refState.data;
 if(!d)return '<div class="empty">Loading…</div>';if(d.error)return `<div class="empty">${depEsc(d.error)}</div>`;
 const code=String(d.code||'').toUpperCase(),per=Number(d.per)||0,bonus=Number(d.bonus)||0,every=Number(d.every)||10,succ=Number(d.success)||0;
 const inRound=succ%every,pct=Math.round(inRound/every*100);
 const head=per>0?`Get <b>${per} PTS</b> for every friend who deposits${bonus>0?` — plus <b>${bonus} PTS</b> extra for every ${every} friends!`:'.'}`:'Share LE888 with your friends.';
 const friends=(d.friends||[]).map(f=>`<div class="dep-item"><span class="dep-noimg">${icon('user')}</span><div class="dep-meta"><b>${depEsc(f.name)}</b><small>${f.status==='rewarded'?'Deposited · '+depWhen(f.rewarded_at||f.created_at):'Added '+depWhen(f.created_at)+' · waiting for first deposit'}</small></div><span class="dep-chip ${f.status==='rewarded'?'approved':'pending'}">${f.status==='rewarded'?(f.points>0?'+'+Number(f.points).toLocaleString('en-SG')+' PTS':'DONE'):'WAITING'}</span></div>`).join('');
 return `<div class="rank-card panel ref-hero">${icon('people')}<h2>INVITE FRIENDS</h2><p>${head}</p></div>
 <section class="form-panel panel ref-code-card"><small class="dep-label">YOUR REFERRAL CODE</small><div class="ref-code"><b>${depEsc(code)}</b><button type="button" class="dep-copy" data-copy="${depEsc(code)}">Copy</button></div><button class="primary-btn" type="button" id="ref-share">Share with a friend</button></section>
 <section class="panel ref-steps"><h3 class="dep-h">How it works</h3><ol><li><b>Share your code</b><span>Send your code <b>${depEsc(code)}</b> to a friend.</span></li><li><b>Friend messages our support</b><span>They tell us your code when we open their account.</span></li><li><b>Friend deposits — you get PTS</b><span>${per>0?`<b>+${per} PTS</b> is added to you automatically.`:'Your reward is added automatically.'}${Number(d.min_deposit)>0?` (Friend needs to deposit at least SGD ${Number(d.min_deposit)}.)`:''}</span></li></ol></section>
 <section class="panel ref-prog"><div class="ref-stats"><div><small>Friends added</small><b>${(d.friends||[]).length}</b></div><div><small>Deposited</small><b>${succ}</b></div><div><small>PTS earned</small><b>${Number(d.earned||0).toLocaleString('en-SG')}</b></div></div>${bonus>0?`<div class="ref-bar-label"><span>Next bonus: <b>+${bonus} PTS</b></span><span>${inRound}/${every}</span></div><div class="ref-bar"><i style="width:${pct}%"></i></div><p class="ref-bar-note">${every-inRound} more friend${every-inRound===1?'':'s'} who deposit${every-inRound===1?'s':''} to get your bonus.</p>`:''}</section>
 <section class="dep-history"><h3 class="dep-h">Your friends</h3>${friends||'<div class="empty">No friends yet. Share your code to start earning!</div>'}</section>`;};
(function(){const prev=render;render=function(){prev();if(state.page!=='invite')return;refLoad();
 const sh=document.querySelector('#ref-share');if(sh)sh.onclick=async()=>{const d=refState.data||{};const code=String(d.code||'').toUpperCase();const url=location.origin+'/install';const text='Join me on LE888! 🎁 Install the app, then message support with my referral code '+code+' to open your account.';
  try{if(navigator.share){await navigator.share({title:'LE888',text,url});}else{await navigator.clipboard.writeText(text+' '+url);toast('Message copied — paste it to your friend.');}}catch(e){}};
 document.querySelectorAll('#screen .ref-code .dep-copy').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(b.dataset.copy);b.textContent='Copied';setTimeout(()=>b.textContent='Copy',1500);}catch(e){toast('Copy unavailable — long-press the code.');}});};})();
PT_TYPE.referral='Referral reward';PT_TYPE.referral_bonus='Referral bonus';
